package com.example.corporate.controller;
import com.example.corporate.dto.*; import com.example.corporate.service.UserService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin/users") public class AdminRestController {private final UserService service; public AdminRestController(UserService s){service=s;} @GetMapping public List<UserResponse> all(){return service.all();} @GetMapping("/{id}") public UserResponse get(@PathVariable Long id){return service.get(id);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public UserResponse create(@RequestBody UserRequest r){return service.create(r);} @PutMapping("/{id}") public UserResponse update(@PathVariable Long id,@RequestBody UserRequest r){return service.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }
